function largestOverlap(img1, img2) {
  let n = img1.length;
  let count = {};
  let maxOverlap = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (img1[i][j] === 1) {
        for (let x = 0; x < n; x++) {
          for (let y = 0; y < n; y++) {
            if (img2[x][y] === 1) {
              let diff = (i - x) + "," + (j - y);
              count[diff] = (count[diff] || 0) + 1;
              maxOverlap = Math.max(maxOverlap, count[diff]);
            }
          }
        }
      }
    }
  }
  return maxOverlap;
}
